/* Grader set v2 ("harder boards"): the owner won all 14 v1 boards played, so v1 cannot tell which boards are hard
   for him. This set keeps the same 6 keepers, rules, refills and loose move limits (v5 rule, calibrate.js, 30 draws;
   never solver-best + small slack) and makes boards harder only by layout. Per kind it shuffles TRIES layouts like v1
   (make-set.js), keeps those the beam solver wins within the limit with no win in 3 moves or fewer, and plays each once
   with a small planner (beam 20, up to 6 moves ahead, re-plans every move, no random moves; tune.js run 1's best
   grader). Kept as hard: the planner loses within the loose limit. Picks PER_KIND per kind: planner losses first, then
   the lowest win rate of the noisy ordinary player at the real limit. Screens, not owner evidence.
   Usage: node prototypes/grader-set/hard/make-hard.js --kind <board id> <part.json>
          node prototypes/grader-set/hard/make-hard.js --merge <out.js> <part.json>... */
const fs=require('node:fs');
const search=require('../../sampler/search'),rules=require('../../sampler/model'),levels=require('../../sampler/levels');
const core=require('../../../solver/engine'),v1=require('../make-set');
const TRIES=30,PER_KIND=2,TRIALS=20,EPSILON=0.2;

function planner(level){
  const maxLength=v1.drought(level)?12:7;let state=rules.create(level);
  while(state.outcome==='playing'){
    const plan=search.solve(level,{beam:20,maxLength,start:state,budget:Math.min(6,state.maxMoves-state.moves)});
    let pick=plan&&plan.path[0];
    if(!pick){const all=rules.chains(state,maxLength);if(!all.length)break;let bh=-Infinity;
      for(const c of all){const n=rules.move(level,state,c);const h=n.outcome==='won'?1e9:search.heuristic(level,n);if(h>bh){bh=h;pick=c;}}}
    state=rules.move(level,state,pick);
  }
  return {outcome:state.outcome,moves:state.moves};
}
function ordinaryWinRate(level){
  const rng=core.makeRng(level.seed*31+7);let wins=0;
  for(let t=0;t<TRIALS;t++)if(search.ordinary(level,{noise:{epsilon:EPSILON,rng}}).outcome==='won')wins++;
  return wins/TRIALS;
}

const args=process.argv.slice(2);
if(args[0]==='--kind'){
  const k=levels.findIndex(b=>b.id===args[1]);if(k<0)throw new Error('no board with id '+args[1]);
  const base=levels[k],rng=core.makeRng(7700+k),kept=[];
  const tries=v1.LIGHT[base.id]?2*TRIES:TRIES;
  for(let c=0;c<tries;c++){
    const level={...base,seed:8000+k*100+c,grid:v1.LIGHT[base.id]?v1.shaken(base,rng,1+c):v1.shuffled(base,rng),moves:20};
    const beam=search.solve(level,{...v1.solveOpts(level),budget:20});
    if(!beam)continue;
    if(v1.drought(level)?beam.moves<2:search.solve(level,{beam:200,maxLength:8,budget:3}))continue;
    let lim;try{lim=v1.limit(level);}catch{continue;}
    const sized={...level,moves:Math.max(lim.moves,beam.moves+4)};
    const p=planner(sized),wr=ordinaryWinRate(sized);
    kept.push({level:sized,beamMoves:beam.moves,plannerLost:p.outcome!=='won',plannerMoves:p.moves,winRate:wr,lim});
    console.error(base.id,c,JSON.stringify({beam:beam.moves,limit:sized.moves,planner:p.outcome,winRate:wr}));
  }
  kept.sort((a,b)=>b.plannerLost-a.plannerLost||a.winRate-b.winRate||b.beamMoves-a.beamMoves||a.level.seed-b.level.seed);
  if(kept.length<PER_KIND)throw new Error(`${base.id}: only ${kept.length} candidates kept`);
  const picked=kept.slice(0,PER_KIND).map((c,n)=>({...c.level,id:`${base.id}-h${n+1}`,
    hardness:{plannerLost:c.plannerLost,plannerMoves:c.plannerMoves,ordinaryWinRate:c.winRate,beamMoves:c.beamMoves,
      candidates:kept.length,plannerLosses:kept.filter(x=>x.plannerLost).length,limitDraws:c.lim.draws,ordinaryWins:c.lim.ordinaryWins,beamWins:c.lim.beamWins}}));
  fs.writeFileSync(args[2],JSON.stringify(picked));
  console.error(base.id,'picked',JSON.stringify(picked.map(p=>p.hardness)));
}else if(args[0]==='--merge'){
  const picked=args.slice(2).flatMap(f=>JSON.parse(fs.readFileSync(f,'utf8')));
  const order=core.makeRng(4496);
  for(let i=picked.length-1;i>0;i--){const j=Math.floor(order()*(i+1));[picked[i],picked[j]]=[picked[j],picked[i]];}
  fs.writeFileSync(args[1],`/* Generated by make-hard.js (grader set v2, harder boards); do not edit by hand. */
(function(root,factory){
  if(typeof module==='object'&&module.exports)module.exports=factory();
  else root.SamplerLevels=factory();
})(typeof globalThis==='object'?globalThis:this,function(){
  'use strict';
  return [
${picked.map(b=>'    '+JSON.stringify(b)).join(',\n')}
  ];
});
`);
  console.error('wrote',args[1],picked.length,'boards');
}else throw new Error('usage: --kind <id> <part.json> | --merge <out.js> <part.json>...');
